UPDATE businesses SET description = 'PEP Strand is the PEP store in Strand Square on Fagan Street, giving Strand residents and holidaymakers an affordable place to shop for the whole family. PEP is one of the best-known budget clothing names in South Africa, and this branch focuses on good everyday value close to home.

The store carries a wide selection of reliable clothing for men, women, children and babies, from wardrobe basics to outfits for school, work and weekends. Alongside the clothing, shoppers will find basic homeware, affordable tech items and other everyday necessities. The branch is also a Paxi point, so customers can send and collect parcels at the counter during the same visit. Its central spot in Strand Square makes it easy to pop in while running other errands in town. PEP is at Strand Square, 21 Fagan Street, Strand.', description_enriched_at = datetime('now') WHERE slug = 'pep-strand' AND description = 'Pep is a fashion and general merchandise store in Strand Square, Strand.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
